import { PullToRefresh, Card, ListRow } from "march/ui"
import { message } from "march/icons"

// bir haber akışı: yenileyince en üste yeni haberler eklenir, durum satırı evreyi söyler
const TITLES = ["Şehirde bisiklet yolu uzuyor", "Hafta sonu hava güneşli", "Yeni kütüphane açıldı", "Sahil konseri cumartesi", "Belediye parkı yeniliyor"]
const PHASES: Record<string, string> = { idle: "Güncel", pull: "Çekiliyor…", ready: "Bırakın", refreshing: "Yenileniyor…" }

export function NewsFeed() {
  let $news = TITLES.slice(0, 3).map((t, i) => ({ id: i, title: t }))
  let $phase = "idle"
  const load = () => new Promise((ok) => setTimeout(ok, 900)).then(() => {
    const id = $news.length
    $news = [{ id, title: `${TITLES[id % TITLES.length]} (yeni)` }, ...$news]
  })
  return <Card title="Haberler" subtitle={() => PHASES[$phase]}>
    <div style={{ height: "260px" }}>
      <PullToRefresh onRefresh={load} onPhase={(p: string) => $phase = p} threshold={64}>
        {() => $news.map((n) => <ListRow lead={message} title={n.title} sub={`Haber #${n.id + 1}`} />)}
      </PullToRefresh>
    </div>
  </Card>
}

import { PullToRefresh, Button } from "march/ui"
import { Icon, arrowDown, arrowUp, hourglass } from "march/icons"

// PullToRefresh'in bütün özellikleri bir arada: onRefresh, threshold, disabled, onPhase, labels, indicator (kendi
// içeriğin), icon, settle, refreshButton, class ve içerik (children)
export function PullToRefreshLab() {
  let $count = 0
  let $phase = "idle"
  let $off = false
  return <div sx={{ flex: "col", gap: 2 }}>
    <div sx={{ flex: ["row", "wrap"], gap: 2 }}>
      <Button size="sm" on:click={() => $off = !$off}>{() => ($off ? "Yenilemeyi aç" : "Yenilemeyi kapat")}</Button>
    </div>
    <p sx={{ text: "sm", color: "muted" }}>{() => `Evre: ${$phase} · yenileme: ${$count}`}</p>
    <div style={{ height: "200px" }}>
      <PullToRefresh class="lab-ptr" threshold={56} settle={180} refreshButton disabled={() => $off}
        onPhase={(p: string) => $phase = p}
        onRefresh={() => new Promise((ok) => setTimeout(ok, 300)).then(() => { $count++ })}
        labels={{ pull: "Çekmeye devam", release: "Bırakın, yenilensin", refreshing: "Yenileniyor…", refresh: "Şimdi yenile" }}
        icon={hourglass}
        indicator={(phase: string) => <Icon of={phase === "ready" ? arrowUp : arrowDown} />}>
        {Array.from({ length: 12 }, (_, i) => <p sx={{ p: 1 }}>{`Öğe ${i + 1}`}</p>)}
      </PullToRefresh>
    </div>
  </div>
}

import { test, expect, renderTest } from "march/testing"
import { PullToRefreshLab } from "./PullToRefreshLab.tsx"

// PullToRefreshLab'in testleri: kaydedince Testler sekmesinde çalışır
test("klavye düğmesi kendi metniyle yenilemeyi çalıştırır", async () => {
  const s = renderTest(() => <PullToRefreshLab />)
  await s.click("Şimdi yenile")
  await s.wait(() => s.sees("yenileme: 1"), { timeout: 2000 })
  expect(s.sees("yenileme: 1")).toBe(true)
})

test("yenilenirken kap aria-busy olur", async () => {
  const s = renderTest(() => <PullToRefreshLab />)
  await s.click("Şimdi yenile")
  expect(s.get(".lab-ptr")?.getAttribute("aria-busy")).toBe("true")
})

test("kapalıyken klavye düğmesi devre dışı", async () => {
  const s = renderTest(() => <PullToRefreshLab />)
  await s.click("Yenilemeyi kapat")
  await s.flush()
  expect((s.find("Şimdi yenile")?.closest("button") as HTMLButtonElement | null)?.disabled).toBe(true)
})

test("içerik kaydırma alanında çizilir", () => {
  const s = renderTest(() => <PullToRefreshLab />)
  expect(s.sees("Öğe 12")).toBe(true)
})
